  gorsel: null,
  secenekler: ["Köpekler gezintide hiçbir zaman acele etmek istemez.", "Köpek gezdirirken onun ihtiyacı gözetilmelidir.", "Köpekler çevrelerini en çok koku alarak tanır.", "Hızlı yürüyüş, köpeğin eve sakin dönmesini sağlar."],
